# -*- coding: utf-8 -*-
T=[]
T.append(dict(id="g-rel",sec="writing",day=5,task="Relative clauses and passives",before="Clinic 1 · Relative clauses and passives: choose",
 emoji="🧩",kicker="THE SENTENCE GLUE",title="Glue Two Sentences<br>Into One",ch1="The glue",
 hook="Welcome, builder. Short sentences are like small blocks. Good writers glue them together into one strong sentence. Today you will learn four glue words and one magic trick called the passive.",
 A="The man <b>which</b> lives next door is a doctor.",B="The man <b>who</b> lives next door is a doctor.",
 cmp="Look at these two sentences. Version A: the man which lives next door is a doctor. Version B: the man who lives next door is a doctor. One glue word fits, and the other does not.",
 verdict="Version B uses who, the glue for people. Version A uses which, the glue for things. Choosing the right glue word shows the reader that you control English.",
 stampA="WRONG GLUE",whyHead="Longer, smarter sentences",whySub="Build a Sentence · email · academic posts",why="Why does this matter? Relative clauses let you pack more information in one sentence. Raters love sentences that are long and still clear. This is how your writing sounds advanced.",
 rule=[
  dict(legend=["s:people","v:things","aux:place","q:possession"],sub="Four glue words",rows=["s:who|v:which / that|aux:where|q:whose"],say="Here are the four glue words. Who is for people. Which or that is for things. Where is for places. And whose shows possession. Choose the glue by the noun that comes before it."),
  dict(sub="Glue for people",rows=["n:The engineer|s:who|n:designed the bridge|n:is my uncle"],note="The engineer designed the bridge + He is my uncle",say="Two sentences: the engineer designed the bridge, and he is my uncle. Glue them with who: the engineer who designed the bridge is my uncle. The glue replaces he."),
  dict(sub="Glue for places and possession",pair=["where","This is the city <b>where</b> I was born.","whose","The student <b>whose</b> project won is my friend."],say="For places, use where: this is the city where I was born. For possession, use whose: the student whose project won is my friend. Never repeat the pronoun after the glue."),
  dict(sub="The magic trick: the passive",rows=["n:Engineers|v:built|n:the lab","n:The lab|aux:was built|n:by engineers"],note="be + past participle",say="Now the magic trick, the passive. Engineers built the lab becomes the lab was built by engineers. We put the object first, and use be plus the past participle. Use it when the action matters more than who did it."),
  dict(sub="Passive without the doer",rows=["n:Spanish|aux:is spoken|n:in Bolivia"],note="Who does it? Not important → skip by",say="Often we do not mention the doer. Spanish is spoken in Bolivia. The report was published in May. We skip by when the doer is obvious or unknown.")],
 trap=dict(es="El hombre <b>que</b> vive aquí. · <b>Se habla</b> español.",esnote="que for everything · se for passives",say1="Now, the trap. Spanish uses one glue word, que, for almost everything: el hombre que vive aquí, el libro que leí. And Spanish makes passives with se: se habla español.",
  es2="el hombre <b>que</b> vive aquí",enbad="the man <b>which</b> lives here",say2="So Spanish speakers use which for people: the man which lives here. And they say: Spanish speaks in Bolivia, using an active verb. Both sound wrong in English.",
  stop="Choose the glue. Use be + participle.",engood="The man <b>who</b> lives here. · Spanish <b>is spoken</b>.",say3="So, stop. Ask: is my noun a person, a thing, a place? Choose who, which, or where. And for se habla, use the passive: is spoken.",
  more=[["Trap 2 · repeated pronoun ✗","The city where I was born <b>it</b> is small.","Fixed ✓","The city where I was born is small.","✂️","The second trap is the repeated pronoun. The glue word already replaces it. Cut it. The city where I was born is small."],
        ["Trap 3 · the participle ✗","The report was <b>wrote</b> by my advisor.","Fixed ✓","The report was <b>written</b> by my advisor.","🔧","The third trap is the verb form. After was, use the past participle, not the past simple. Written, not wrote. Built, not build."]]),
 quiz=["The professor ___ taught us was excellent.",["which","who","whose"],1],
 quizsay="Quick quiz. The professor, blank, taught us was excellent. People need which glue? Think. ... The answer is B. Who. The professor who taught us was excellent.",
 fix=dict(sub="Fix the sentence",row="n:The report|aux:was|g:wrote|v:written|n:by my advisor",say="Fix this one. The report was wrote by my advisor. After was, we need the past participle. The report was written by my advisor."),
 recap=["<b>who</b> people · <b>which</b> things · <b>where</b> places · <b>whose</b> owner","<b>Do not repeat</b> the pronoun after the glue","Passive = <b>be + past participle</b>"],
 recapsay="Three things to remember. One, who for people, which or that for things, where for places, whose for possession. Two, never repeat the pronoun. Three, the passive is be plus the past participle.",
 done="Master builder!",donesay="Master builder! You can now glue short sentences into strong ones. Go to the practice. Remember: choose the glue by the noun. Good luck!",
 check=dict(why1="People need who.",q2="Choose the correct sentence.",a2="The report was written by my advisor.",w2=["The report was wrote by my advisor.","The report written by my advisor.","The report was writing by my advisor."],why2="After was, use the past participle.")))
T.append(dict(id="g-art",sec="writing",day=5,task="Articles, plurals and uncountable nouns",replace="Clinic 2 · Articles, plurals and uncountable nouns: notice",
 emoji="🛂",kicker="ARTICLE AIRPORT",title="A, An, The<br>or Nothing?",ch1="Check in",
 hook="Welcome to Article Airport. Before a noun can travel through your sentence, it must pass a check. Does it need a, an, the, or nothing at all? Today you will learn the four gates.",
 A="He gave me <b>an advice</b>.",B="He gave me <b>some advice</b>.",
 cmp="Look at these two sentences. Version A: he gave me an advice. Version B: he gave me some advice. One of them was stopped at the gate.",
 verdict="Version A was stopped. The noun advice is uncountable, so it cannot take a or an, and it has no plural. Version B uses some, which works with uncountable nouns.",
 stampA="STOPPED",whyHead="The most common error for Spanish speakers",whySub="Articles and plurals appear in every paragraph",why="Why does this matter? Articles are tiny words, but you use them in almost every sentence. Getting them right makes your writing sound natural and professional.",
 rule=[
  dict(legend=["s:a / an","v:the","aux:no article"],sub="Four gates",rows=["s:a / an|v:the|aux:some|n:nothing"],say="There are four gates. A or an for one new thing. The for a specific thing you both know. Some for an amount. And no article for general ideas. Let us visit each gate."),
  dict(sub="A / an: one new thing",rows=["n:I read|s:an|n:article","n:It was|s:a|n:long article"],note="Use the SOUND, not the letter: a university · an hour",say="A or an introduces one new thing. I read an article. Choose by sound, not by letter: a university, because it starts with a y sound. An hour, because the h is silent."),
  dict(sub="The: we both know which",rows=["n:I read an article.|v:The|n:article was long."],note="Mentioned before · only one · specific",say="Use the when both people know which one you mean. I read an article. The article was long. Use the also for only-one things: the sun, the library on campus."),
  dict(sub="Uncountable nouns",pair=["✗ countable","an advice · advices · informations","✓ uncountable","<b>some</b> advice · a piece of advice · much information"],say="Uncountable nouns are things we do not count: advice, information, furniture, news, equipment. No a, no plural. Say some advice, a piece of advice, much information."),
  dict(sub="General ideas: no article",rows=["n:I like|aux:music|n:.","aux:Life|n:is difficult."],note="plural and uncountable nouns in general → no article",say="When you talk about things in general, use no article. I like music. Life is difficult. Prices are rising. Use the only when you mean specific music or a specific life.")],
 trap=dict(es="<b>La</b> vida es difícil. · Me gusta <b>la</b> música.",esnote="Spanish uses the article for general nouns",say1="Now the trap. Spanish uses the article with general ideas: la vida es difícil, me gusta la música. That is correct in Spanish, because the article is almost always needed.",
  es2="me gusta <b>la</b> música",enbad="I like <b>the</b> music",say2="So Spanish speakers write: I like the music, meaning music in general. In English, the music means one specific music that we both know.",
  stop="General? No article.",engood="I like music. Life is difficult.",say3="So, stop. If you mean music in general, say music. If you mean one specific piece, say the music. Ask yourself: general or specific?",
  more=[["Trap 2 · informations ✗","She gave me <b>many informations</b>.","Fixed ✓","She gave me <b>a lot of information</b>.","🔧","The second trap is plural forms. Information, advice and news never take an s. Use a lot of, much, or some. A lot of information."]]),
 quiz=["I need ___ about the course.",["an information","some information","informations"],1],
 quizsay="Quick quiz. I need blank about the course. Information is uncountable. ... The answer is B. Some information. No a, and no s.",
 fix=dict(sub="Fix the sentence",row="s:I|v:like|g:the|n:music|n:in general",say="Fix this one. I like the music in general. General ideas need no article. Remove the, and say: I like music in general."),
 recap=["<b>a / an</b>: one new thing (by sound)","<b>the</b>: specific, already known","<b>no article</b>: general ideas · uncountables have no plural"],
 recapsay="Three things to remember. One, a or an for one new thing, by sound. Two, the for something specific that both people know. Three, no article for general ideas, and uncountable nouns never take s.",
 done="Boarding complete!",donesay="Boarding complete! Your nouns have passed every gate. Now go to the practice. Remember: general or specific? Countable or uncountable? Safe travels!",
 check=dict(why1="Uncountable nouns take some, not a or an.",q2="Choose the correct sentence.",a2="I like music in general.",w2=["I like the music in general.","I like a music in general.","I like musics in general."],why2="General ideas need no article.")))
T.append(dict(id="g-rep",sec="writing",day=6,task="Reported speech and conditionals",before="Clinic 1 · Reported speech and conditionals: choose",
 emoji="📞",kicker="THE TELEPHONE GAME",title="What Did<br>She Say?",ch1="The message",
 hook="Welcome to the telephone game. Someone says a sentence, and you pass it on. But when you retell it, some words change. Today you will learn how, and also how to talk about imaginary situations.",
 A="She <b>said me</b> to rest.",B="She <b>told me</b> to rest.",
 cmp="Look at these two sentences. Version A: she said me to rest. Version B: she told me to rest. The message is the same, but one of them has a broken telephone line.",
 verdict="Version A is broken. The verb say cannot have a person right after it. Tell can: she told me. So say and tell look similar, but they follow different rules.",
 stampA="BROKEN LINE",whyHead="Reporting what others say",whySub="Emails · Academic posts · reading classmates' views",why="Why does this matter? In emails and discussion posts you often report what someone said. And imaginary situations, with if, help you explain consequences and opinions.",
 rule=[
  dict(legend=["s:said","v:becomes"],sub="Step back one tense",rows=["s:I am tired|v:→ she said she was tired"],say="When you report speech in the past, the tense steps back. I am tired becomes she said that she was tired. Will becomes would. Can becomes could."),
  dict(sub="Say or tell?",pair=["say (no person)","She <b>said</b> that she was tired.","tell (person)","She <b>told me</b> that she was tired."],say="Say does not take a person: she said that she was tired. Tell needs a person: she told me that she was tired. And for commands, tell me to: the doctor told me to rest."),
  dict(sub="Reported questions: statement order",rows=["n:He asked|q:where|s:I|v:lived"],note="No helper · yes/no questions → if / whether",say="Reported questions use statement order, just like embedded questions. He asked where I lived. For yes or no questions, add if or whether. She asked if I had finished."),
  dict(sub="Second conditional: imaginary now",rows=["n:If|s:I|v:had|n:time,|aux:I would help"],note="if + past simple, would + base verb",say="Now the imaginary world. For a situation that is not real now, use if plus past simple, and would plus the base verb. If I had time, I would help. I do not have time, so it is imaginary."),
  dict(sub="Third conditional: imaginary past",rows=["n:If|s:I|v:had known,|aux:I would have called"],note="if + past perfect, would have + participle",say="For the imaginary past, use if plus past perfect, and would have plus the past participle. If I had known, I would have called. But I did not know, and I did not call.")],
 trap=dict(es="Ella me <b>dijo</b> que descansara. · Si <b>tuviera</b> tiempo…",esnote="decir for say and tell · subjunctive in Spanish",say1="Now the trap. Spanish uses one verb, decir, for both say and tell: ella me dijo que descansara. And Spanish uses the subjunctive for imaginary situations: si tuviera tiempo.",
  es2="ella me <b>dijo</b> que descansara",enbad="she <b>said me</b> to rest",say2="So Spanish speakers translate dijo me as said me: she said me to rest. And for conditionals they write: if I would have time. Both are wrong in English.",
  stop="Tell me, but say that. Never would after if.",engood="She <b>told me</b> to rest. · If I <b>had</b> time…",say3="So, stop. Use told me, or said that. And in an if clause, never use would. Put would only in the result part.",
  more=[["Trap 2 · reported question order ✗","He asked me where <b>did I</b> live.","Fixed ✓","He asked me where <b>I lived</b>.","🔄","The second trap is word order in a reported question. Use statement order: where I lived. No did."],
        ["Trap 3 · would in the if-clause ✗","If I <b>would have</b> time, I would help.","Fixed ✓","If I <b>had</b> time, I would help.","✂️","The third trap. Would never goes in the if clause. If I had time, I would help. If would, and would, never together."]]),
 quiz=["She ___ me that the exam was cancelled.",["said","told","spoke"],1],
 quizsay="Quick quiz. She, blank, me that the exam was cancelled. There is a person after the verb. ... The answer is B. She told me. Told always takes a person.",
 fix=dict(sub="Fix the sentence",row="n:If I|g:would have|v:had|n:time, I would help",say="Fix this one. If I would have time, I would help. Remove would from the if clause, and use the past simple: if I had time, I would help."),
 recap=["<b>say that</b> · <b>tell me</b> · tenses step back","Reported questions: <b>statement order</b>","<b>if + past → would</b> · <b>if + past perfect → would have</b>"],
 recapsay="Three things to remember. One, say that, but tell me, and tenses step back. Two, reported questions use statement order. Three, if plus past gives would, and if plus past perfect gives would have.",
 done="Line connected!",donesay="The line is connected. Now go to the practice and remember: tell me, statement order, and never would after if. Good luck!",
 check=dict(why1="Tell takes a person; say does not.",q2="Choose the correct sentence.",a2="If I had time, I would help.",w2=["If I would have time, I would help.","If I have time, I would help.","If I had time, I will help."],why2="No would in the if clause.")))
T.append(dict(id="g-pun",sec="writing",day=6,task="Punctuation: commas and run-on sentences",replace="Clinic 2 · Punctuation: commas and run-on sentences: notice",
 emoji="🚔",kicker="THE COMMA POLICE",title="Stop the<br>Comma Splice",ch1="Police report",
 hook="Welcome to the Comma Police. Commas are tiny, but they keep sentences in order. Some commas do their job. Others break the law. Today you will learn to arrest the bad ones.",
 A="I was late<b>,</b> I missed the quiz.",B="I was late<b>, so</b> I missed the quiz.",
 cmp="Look at these two sentences. Version A: I was late, I missed the quiz. Version B: I was late, so I missed the quiz. One of them is holding two sentences together with a weak comma.",
 verdict="Version A is a comma splice. Two complete sentences are tied by only a comma, which is too weak. Version B adds so, a conjunction, and now the comma has a partner.",
 stampA="COMMA SPLICE",whyHead="Clear sentences, clear score",whySub="Run-on sentences are the most visible punctuation error",why="Why does this matter? Raters notice comma splices immediately, and they appear in a lot of fast writing. Fixing them is one of the quickest ways to make your writing look more careful.",
 rule=[
  dict(legend=["s:complete sentence","v:conjunction"],sub="Two sentences need a strong link",rows=["s:I was late|v:, so|s:I missed the quiz"],say="Two complete sentences need a strong link. A comma plus a conjunction like and, but or so. I was late, so I missed the quiz. A comma alone is too weak."),
  dict(sub="Three ways to fix a splice",rows=["s:I was late|n:. |s:I missed it","s:I was late|v:;|s:I missed it","s:I was late|v:, so|s:I missed it"],note="full stop · semicolon · comma + conjunction",say="There are three fixes. Use a full stop. Use a semicolon. Or use a comma and a conjunction. Any of them works. A comma alone does not."),
  dict(sub="Introductory clause: add a comma",pair=["✗","Although it was raining we went out.","✓","Although it was raining<b>,</b> we went out."],say="When a sentence starts with although, because, if or when, put a comma after that first part. Although it was raining, we went out. The comma tells the reader where the main idea begins."),
  dict(sub="However, therefore: semicolon before, comma after",rows=["s:It is important|v:;|aux:however,|s:it is costly"],note="; however,  · ; therefore,  · ; moreover,",say="Words like however and therefore are not conjunctions. Put a semicolon or a full stop before them, and a comma after. It is important; however, it is costly."),
  dict(sub="No comma between subject and verb",pair=["✗","My brother<b>,</b> lives in Sucre.","✓","My brother lives in Sucre."],say="One more rule. Never put a single comma between the subject and the verb. My brother lives in Sucre. Only use two commas if you add extra information in the middle.")],
 trap=dict(es="Llegué tarde<b>,</b> perdí el examen.",esnote="Spanish accepts a comma between two clauses",say1="Now the trap. In Spanish, a comma between two short clauses is often acceptable: llegué tarde, perdí el examen. It sounds natural and readable.",
  es2="llegué tarde<b>,</b> perdí el examen",enbad="I was late<b>,</b> I missed the exam",say2="So Spanish speakers copy it into English: I was late, I missed the exam. In English, that is a comma splice. It is one of the most common errors.",
  stop="A comma alone cannot join sentences",engood="I was late, <b>so</b> I missed the exam.",say3="So, stop. Check every comma. If it connects two complete sentences, add a conjunction, or replace it with a semicolon or a full stop.",
  more=[["Trap 2 · however ✗","It is important<b>,</b> however it is costly.","Fixed ✓","It is important<b>;</b> however, it is costly.","🔧","The second trap is however. It cannot join two sentences with a comma. Use a semicolon before it, and a comma after."]]),
 quiz=["Which sentence is correct?",["I was late, I missed it.","I was late, so I missed it.","I was late so, I missed it."],1],
 quizsay="Quick quiz. Which sentence is correct? Think. ... The answer is B. I was late, so I missed it. A comma plus a conjunction.",
 fix=dict(sub="Fix the sentence",row="s:She studied hard|g:,|v:, so|s:she passed",say="Fix this one. She studied hard, she passed. Add so after the comma. She studied hard, so she passed."),
 recap=["<b>Comma + conjunction</b> (and, but, so) · or <b>;</b> · or <b>full stop</b>","<b>Comma after</b> an introductory clause","<b>; however,</b> · no comma between subject and verb"],
 recapsay="Three things to remember. One, join two sentences with a comma and a conjunction, or a semicolon, or a full stop. Two, add a comma after an introductory clause. Three, semicolon before however, and no comma between subject and verb.",
 done="Case dismissed!",donesay="Case dismissed! No more comma splices on your watch. Go to the practice. Remember: a comma alone cannot join two sentences. Good luck, officer!",
 check=dict(why1="A comma needs a conjunction to join two sentences.",q2="Choose the correct sentence.",a2="The study is important; however, it is expensive.",w2=["The study is important, however it is expensive.","The study is important however, it is expensive.","The study is important; however it, is expensive."],why2="Semicolon before however, comma after.")))
